class Solution:

	def CamelCase(self, N, Dictionary, Pattern):
		s = ''
		l = []
		ll = {}
		ll1 = {}
		for i in range(len(Dictionary)):
			for j in Dictionary[i]:
				if j.isupper():
					s = s + j
			ll[Dictionary[i]] = s
			if Dictionary[i] not in ll1:
				ll1[Dictionary[i]] = 1
			else:
				ll1[Dictionary[i]] += 1
			s = ''
		ml = []
		for i in ll:
			j = 0
			while j < len(Pattern):
				if len(ll[i]) >= len(Pattern):
					if ll[i][j] == Pattern[j]:
						j = j + 1
					else:
						break
				else:
					break
			if j == len(Pattern):
				ml = ml + [i] * ll1[i]
		return sorted(ml)
